const Qx = Ox, Qy = Oy - leg * s;       // vertical leg
// triangle
H.path([[Ox,Oy],[Px,Py],[Qx,Qy]], { color: H.colors.accent, width: 3, fill: "rgba(124,196,255,0.12)", close: true });
// right-angle marker
const m = 13;
H.path([[Ox+m,Oy],[Ox+m,Oy-m],[Ox,Oy-m]], { color: H.colors.sub, width: 1.5 });
// 45 arcs at P and Q
const arc = (cx, cy, a0, a1, r, col) => {
  const pts = [];
  for (let i = 0; i <= 16; i++) { const a = a0 + (a1 - a0) * i / 16; pts.push([cx + r*Math.cos(a), cy + r*Math.sin(a)]); }
  H.path(pts, { color: col, width: 2 });
};
